176: function stepEvidence(task, stage, host) {
177:   const step = task.steps[stage.id];
178:   if (!evidenceFor(task, step.evidence_ids, host)) return false;
179:   const evidence = step.evidence_ids.map(id => task.evidence.find(e => e.id === id));
180:   const scoped = evidence.filter(e => e.skill === stage.skill && e.request_binding === digest(host.requests[stage.id]) && e.claims?.includes(`stage:${stage.id}`));
181:   if (!scoped.length) return false;
182:   if (stage.skill === 'safe-code-review' && !scoped.some(e => e.kind === 'review' && e.independent === true
183:       && e.review_basis && e.review_basis === host.reviewBinding)) return false;
184:   if (stage.skill === 'bug-root-cause-analysis' && !scoped.some(e => e.signal_ids?.length
185:       && e.signal_ids.every(id => task.evidence.some(signal => signal.id === id && signal.kind === 'signal' && signal.task_binding === taskBinding(task)
186:         && evidenceValidity(signal, host).status === 'valid')))) return false;
187:   return true;
188: }
