190: /** Recompute a decision every time. No imported context field grants execution authority. */
191: export function nextAction(task, host) {
192:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
193:   const workflow = definition(task, host.registry, host.inventory);
194:   assert(Object.keys(task.steps).length === workflow.stages.length && workflow.stages.every(s => task.steps[s.id]), 'Task stages differ from Registry');
195:   if (!host.scopeReviewed) return { action: 'evidence_insufficient', reason: 'risk_and_dependency_scope_not_reviewed' };
196:   if (workflow.stages.length > 1 && !host.continuationAuthorized) return { action: 'permission_blocked', reason: 'continuous_workflow_not_authorized' };
197:   if (host.openDecisions?.length) return { action: 'decision_required', skill: 'requirements-clarification', reason: host.openDecisions.join(', ') };
198:   if (host.activeStops?.length) return { action: 'blocked', reason: host.activeStops.join(', ') };
199:   const recovery = recoveryBinding(task, host);
200:   const recoveryCheck = recovery && host.recoveryChecks?.get(recovery);
201:   if (recovery && (!recoveryCheck?.source || recoveryCheck.reconciled !== true)) return { action: 'blocked', reason: 'recovered_execution_state_needs_reconciliation' };
202:   // Unknown effects cannot disappear when an optional predicate or prerequisite changes.
203:   const inflight = workflow.stages.find(stage => ['running', 'interrupted'].includes(task.steps[stage.id].status));
204:   if (inflight) return { stage: inflight.id, skill: inflight.skill, action: 'blocked', reason: 'inflight_operation_needs_reconciliation' };
205:   const uncertain = workflow.stages.find(stage => task.steps[stage.id].effect_state === 'uncertain');
206:   if (uncertain) return { stage: uncertain.id, skill: uncertain.skill, action: 'validation_failed', reason: 'failed_operation_needs_reconciliation' };
207:   const completed = new Set();
208:   for (const stage of workflow.stages) {
209:     const step = task.steps[stage.id];
210:     if (stage.prerequisites.some(id => !completed.has(id))) continue;
211:     if (step.request_binding && step.request_binding !== digest(host.requests?.[stage.id])) {
212:       return { stage: stage.id, skill: stage.skill, action: 'evidence_insufficient', reason: 'operation_scope_changed' };
213:     }
214:     const applies = condition(task, stage.condition, host);
215:     const decision = { stage: stage.id, skill: stage.skill };
216:     const stopAssessments = [...new Set([...(workflow.stop_conditions ?? []), ...stage.stop_conditions])].map(name => [name, condition(task, name, host)]);
217:     const stop = stopAssessments.find(([, value]) => value === true);
218:     if (stop) return { ...decision, action: 'blocked', reason: `stop_condition:${stop[0]}` };
219:     const unknownStop = stopAssessments.find(([, value]) => value === undefined);
220:     if (unknownStop) return { ...decision, action: 'evidence_insufficient', reason: `stop_condition_unknown:${unknownStop[0]}` };
221:     if (applies === undefined) return { ...decision, action: 'evidence_insufficient', reason: `condition_unknown:${stage.condition}` };
222:     // Completed effects stay protected even when applicability changes. A new receipt
223:     // is not a reconciliation of the previous attempt's potentially different effects.
224:     const wasCompleted = ['completed', 'reused'].includes(step.status);
225:     const effectful = step.effect_state === 'known' || writes(stage, host)
226:       || host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files');
227:     if (stage.type === 'skill' && wasCompleted) {
228:       const denied = permission(stage.skill, stage, task, host);
229:       if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
230:       if (!stepEvidence(task, stage, host) && effectful) return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };

231:     }
232:     if (!applies) {
233:       if (!stage.optional) return { ...decision, action: 'evidence_insufficient', reason: `required_condition_false:${stage.condition}` };
234:       // Applicability must not erase a completed operation or its known effects.
235:       if (['completed', 'reused'].includes(step.status)) { completed.add(stage.id); continue; }
236:       if (step.status !== 'skipped' || step.condition_binding !== digest(host.conditions[stage.condition])) return { ...decision, action: 'skip', reason: `not_applicable:${stage.condition}` };
237:       completed.add(stage.id); continue;
238:     }
239:     if (stage.type === 'gate') {
240:       const children = workflow.stages.filter(s => s.approval_gate === stage.id);
241:       if (!children.length) return { ...decision, action: 'permission_blocked', reason: 'gate_has_no_consumer' };
242:       for (const child of children) {
243:         const denied = permission(child.skill, child, task, host);
244:         if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
245:       }
246:       // Always re-evaluate gates against host grants, never reuse persisted approval.
247:       if (step.status !== 'completed') return { ...decision, action: 'approve', reason: 'existing_scoped_host_authorization' };
248:       completed.add(stage.id); continue;
249:     }
250:     const denied = permission(stage.skill, stage, task, host);
251:     if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
252:     if (['completed', 'reused'].includes(step.status) && stepEvidence(task, stage, host)) {
253:       completed.add(stage.id); continue;
254:     }
255:     const failure = step.status === 'validation_failed';
256:     if (failure) return { ...decision, action: 'validation_failed', reason: step.reason || 'explicit_retry_required' };
257:     // Risk checks are additive obligations referencing existing Skills, not new workflows.
258:     if (potentiallyEffectful(stage, host)) {
259:       const gap = (host.risks ?? []).flatMap(r => host.registry.coordination?.risk_requirements?.[r]?.before_write ?? [{ claim: `unclassified-risk:${r}` }])
260:         .find(r => !requirement(task, r, host));
261:       if (gap) return { ...decision, action: 'risk_check', requirement: gap, reason: 'risk_requires_additional_evidence' };
262:     }
263:     const candidate = host.reuse?.[stage.id];
264:     if (candidate) {
265:       const provisional = copy(task); provisional.steps[stage.id].evidence_ids = candidate;
266:       if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: candidate, reason: 'valid_existing_result' };
267:     }
268:     if ((writes(stage, host) || step.effect_state === 'known' || host.requests[stage.id].capabilities.some(c => c !== 'read_files')) && ['completed', 'reused'].includes(step.status)) {
269:       return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
270:     }
271:     return { ...decision, action: 'execute', reason: ['completed', 'reused'].includes(step.status) ? 'prior_evidence_stale_or_unknown' : 'applicable_stage', mode: host.execution === 'same_agent' ? 'same_agent' : 'manual_handoff' };
272:   }
273:   if (completed.size !== workflow.stages.length) return { action: 'evidence_insufficient', reason: 'unresolved_dependencies' };
274:   const obligations = [
275:     ...task.acceptance.map(id => ({ claim: `acceptance:${id}` })),
276:     ...([...completed].some(id => {
277:       const stage = workflow.stages.find(s => s.id === id);
278:       return task.steps[id].status !== 'skipped'
279:         && ['feature-implementation', 'safe-fix-implementation', 'safe-test-implementation'].includes(stage.skill);
280:     }) ? [{ claim: 'behavior-validation', kind: 'test' }] : []),
281:     ...(host.deliveryRequirements ?? []),
282:     ...(host.risks ?? []).flatMap(r => {
283:       const rules = host.registry.coordination?.risk_requirements?.[r];
284:       return rules ? [...rules.before_write, ...rules.before_delivery] : [{ claim: `unclassified-risk:${r}` }];
285:     }),
286:   ];
287:   // Passing receipts never silently supersede a later/contradictory current failure.
288:   // A trusted host must investigate flakiness and explicitly link an observed rerun.
289:   for (const failed of task.evidence.filter(e => e.task_binding === taskBinding(task) && e.kind === 'test' && e.result === 'fail')) {
290:     if (evidenceValidity(failed, host).status !== 'failed') continue;
291:     const resolution = host.failureResolutions?.get(digest(failed));
292:     const replacement = resolution?.source && task.evidence.find(e => e.id === resolution.replacement);
293:     const identity = e => digest({ command: e.command, cwd: e.cwd, bindings: e.bindings, environment: e.environment });
294:     if (!replacement || replacement.task_binding !== taskBinding(task) || replacement.kind !== 'test'
295:         || evidenceValidity(replacement, host).status !== 'valid' || identity(replacement) !== identity(failed)
296:         || !(Date.parse(replacement.recorded_at) > Date.parse(failed.recorded_at))) {
297:       return { action: 'validation_failed', reason: 'unresolved_current_test_failure', evidence_id: failed.id };
298:     }
299:   }
300:   const missing = obligations.filter(r => !requirement(task, r, host));
301:   if (task.unresolved.length || missing.length) return { action: 'evidence_insufficient', reason: 'delivery_not_proven', missing };
302:   return { action: 'complete', reason: 'applicable_stages_and_acceptance_proven', release_authorized: false };
303: }
