310: export function advance(task, host) {
311:   const action = nextAction(task, host);
312:   if (['skip', 'approve', 'reuse', 'execute'].includes(action.action)) {
313:     const step = task.steps[action.stage];
314:     step.status = { skip: 'skipped', approve: 'completed', reuse: 'reused', execute: 'running' }[action.action];
315:     step.reason = action.reason;
316:     if (['execute', 'reuse'].includes(action.action)) step.request_binding = digest(host.requests[action.stage]);
317:     if (action.action === 'execute') {
318:       step.attempts++;
319:       step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'uncertain' : 'none';
320:     }
321:     if (action.action === 'skip') {
322:       const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === action.stage);
323:       step.condition_binding = digest(host.conditions[stage.condition]);
324:     }
325:     if (action.action === 'reuse') step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'known' : 'none';
326:     if (action.evidence_ids) step.evidence_ids = action.evidence_ids;
327:     event(task, action.stage, step.status, action.reason);
328:   }
329:   task.next_actions = [action];
330:   return action;
331: }
