333: export function finishStep(task, stageId, evidenceIds, host, failureReason = null) {
334:   const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === stageId);
335:   const step = task.steps[stageId];
336:   assert(stage && step?.status === 'running', 'Only a running stage may finish');
337:   assert(step.request_binding === digest(host.requests[stageId]), 'Operation scope changed while running');
338:   const denied = permission(stage.skill, stage, task, host);
339:   assert(!denied, denied);
340:   if (failureReason) { step.status = 'validation_failed'; step.reason = failureReason; step.evidence_ids = [...evidenceIds]; }
341:   else {
342:     const provisional = copy(task); provisional.steps[stageId].evidence_ids = evidenceIds;
343:     assert(stepEvidence(provisional, stage, host), 'Completion requires valid, scoped evidence and independent review');
344:     step.evidence_ids = [...evidenceIds]; step.status = 'completed'; step.effect_state = step.effect_state === 'none' ? 'none' : 'known';
345:   }
346:   event(task, stageId, step.status, failureReason || 'observed_completion');
347: }
