349: /** Reopening is an explicit host decision; only descendants are reopened.
350:  * Evidence is retained, so still-valid independent checks can be reused.
351:  */
352: export function reopen(task, stageId, host, { reason, source, safeToRetry = false } = {}) {
353:   assert(reason && source, 'Reopen requires a sourced reason');
354:   const workflow = definition(task, host.registry, host.inventory);
355:   assert(task.steps[stageId], 'Unknown stage');
356:   const affected = new Set([stageId]);
357:   let changed = true;
358:   while (changed) { changed = false; for (const stage of workflow.stages) {
359:     if (!affected.has(stage.id) && stage.prerequisites.some(id => affected.has(id))) { affected.add(stage.id); changed = true; }
360:   } }
361:   for (const id of affected) {
362:     const stage = workflow.stages.find(s => s.id === id);
363:     if (['running', 'interrupted'].includes(task.steps[id].status)
364:         || task.steps[id].effect_state === 'uncertain'
365:         || ((writes(stage, host) || task.steps[id].effect_state === 'known' || host.requests?.[id]?.capabilities?.some(c => c !== 'read_files')) && ['completed', 'reused', 'validation_failed'].includes(task.steps[id].status))) {
366:       assert(safeToRetry && host.reconciled?.has(reconciliationBinding(task, id, host)), 'Unknown side effects must be reconciled before retry');
367:     }
368:   }
369:   for (const id of affected) {
370:     const previous = task.steps[id].request_binding;
371:     task.steps[id].status = 'pending'; task.steps[id].effect_state = 'reconciled';
372:     delete task.steps[id].request_binding;
373:     event(task, id, 'pending', `${reason} (${source})`);
374:     if (previous) task.history.at(-1).previous_request_binding = previous;
375:   }
376: }
