378: export function encodeTask(task) { return JSON.stringify(task, null, 2) + '\n'; }
379: export function restoreTask(serialized, registry, inventory) {
380:   const task = JSON.parse(serialized);
381:   assert(task.schema_version === 2 && task.id && task.goal && Array.isArray(task.acceptance) && task.acceptance.length, 'Invalid Task Context');
382:   assert(Boolean(task.workflow_id) !== Boolean(task.skill_id), 'Choose one registered workflow or one existing Skill');
383:   assert(task.acceptance.every(item => typeof item === 'string' && item.length)
384:     && new Set(task.acceptance).size === task.acceptance.length, 'Invalid acceptance IDs');
385:   const shape = createTask({ id: task.id, goal: task.goal, acceptance: task.acceptance, workflow_id: task.workflow_id, skill_id: task.skill_id }, registry, inventory);
386:   assert(Object.keys(task).every(key => Object.hasOwn(shape, key)) && Object.keys(shape).every(key => Object.hasOwn(task, key)), 'Unexpected or missing Task Context fields');
387:   for (const name of ['decisions', 'risks', 'permission_refs', 'evidence', 'changes', 'unresolved', 'history', 'next_actions']) assert(Array.isArray(task[name]), `Invalid ${name}`);
388:   assert(task.scope && Array.isArray(task.scope.files) && Array.isArray(task.scope.modules) && Array.isArray(task.scope.interfaces), 'Invalid scope');
389:   runtimeTasks.add(task);
390:   const workflow = definition(task, registry, inventory);
391:   assert(task.steps && Object.keys(task.steps).length === workflow.stages.length, 'Invalid step set');
392:   for (const stage of workflow.stages) {
393:     const step = task.steps[stage.id];
394:     assert(step && states.has(step.status) && Number.isInteger(step.attempts) && step.attempts >= 0 && Array.isArray(step.evidence_ids), 'Invalid step state');
395:     if (step.status === 'running') step.status = 'interrupted';
396:   }
397:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
